{CALL
    DECLARE
        v_sql varchar2(500);
    BEGIN
        v_sql := 'CREATE SEQUENCE ${tableName}_SEQ START WITH 1 MAXVALUE 99999999 MINVALUE 1 CYCLE CACHE 20 NOORDER';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(PHONE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(REQDATE, RSLT)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX3 ON ${tableName}(PRODUCT_CODE, RSLT)';
        execute immediate v_sql;
    END
}

{CALL
    DECLARE
    v_sql varchar2(500);
    BEGIN
    v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(PHONE)';
    execute immediate v_sql;

    v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(REQDATE, RSLT)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX3 ON ${tableName}(PRODUCT_CODE, RSLT)';
    execute immediate v_sql;
    END
}

UPDATE ${tableName}
SET
    STATUS = CASE WHEN STATUS = '3' THEN STATUS ELSE #{parameter.messageStatus} END
    , ROUTE_ID = #{parameter.routeId}
    , RSLT = #{parameter.doneCode}
    , RSLTDESC = #{parameter.doneCodeDescription}
    , RPTDATE = TO_DATE(#{parameter.doneDate}, 'YYYYMMDDHH24MISS')
    , TELCO = #{parameter.doneTelco}
    , PRODUCT_CODE = #{parameter.doneProduct}
    , FALLBACK_REASON = #{parameter.doneFallbackCode}
    , FALLBACK_REASON_DESC = #{parameter.doneFallbackDetail}
WHERE
    MSGKEY IS NULL
    MSGKEY = #{parameter.key}

DELETE FROM ${tableName}
WHERE
    MSGKEY IS NULL
    MSGKEY = #{parameter.key}
